import React from 'react';
import { 
  Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, Typography 
} from '@mui/material';

const MeetingList = ({ meetings }) => {
  if (meetings.length === 0) {
    return <Typography variant="body1" sx={{ mt: 2 }}>No meetings scheduled for this team.</Typography>;
  }

  return (
    <TableContainer component={Paper} sx={{ mt: 3, mb: 3 }}>
      <Table sx={{ minWidth: 650 }} aria-label="meetings table">
        <TableHead>
          <TableRow>
            <TableCell><strong>Start Time</strong></TableCell>
            <TableCell><strong>End Time</strong></TableCell>
            <TableCell><strong>Description</strong></TableCell>
            <TableCell><strong>Room</strong></TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
            {meetings.map((meeting) => (
            <TableRow
              key={meeting.id}
              sx={{ '&:last-child td, &:last-child th': { border: 0 } }}
            >
              <TableCell>{new Date(meeting.startTime).toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' })}</TableCell>
              <TableCell>{new Date(meeting.endTime).toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' })}</TableCell>
              <TableCell>{meeting.description}</TableCell>
              <TableCell>{meeting.room}</TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
};

export default MeetingList;
